          "id": "code-ml-25-1-ch25_1_scratch",
          "title": "First-Principles NumPy: 3-Buffer Apache Arrow String vs PyObject* & Parquet Zone-Map Pushdown",
          "language": "python",
          "filename": "25_1_arrow_buffers_and_parquet_pushdown.py",
          "code": "import sys\nimport numpy as np\n\nrng = np.random.default_rng(251)\n\n# -----------------------------------------------------------------------------\n# 1) First-Principles: Apache Arrow String Array (3 Buffer Kontigu) vs Python Object List\n# -----------------------------------------------------------------------------\nN = 4000\nmerchants = [f\"MERCH_{i % 120:04d}_JKT\" for i in range(N)]\nnull_mask = (np.arange(N) % 25 == 0)  # 4% missing values\npy_col = [None if null_mask[i] else merchants[i] for i in range(N)]\n\n# Jejak RAM daftar objek Python klasik (setiap string = alokasi PyUnicode terpisah + pointer 8B)\nptr_array_bytes = sys.getsizeof(py_col)\n# Tanpa string interning: hitung biaya aktual alokasi unik per baris seperti hasil pd.read_csv(dtype=object)\npy_heap_bytes = ptr_array_bytes + sum(\n    sys.getsizeof(f\"MERCH_{i % 120:04d}_JKT\") if not null_mask[i] else 0\n    for i in range(N)\n)\n\n# Representasi Apache Arrow String Array murni di atas buffer NumPy kontigu:\n#   (a) Validity Bitmap  : ceil(N / 8) byte (1 bit per baris: 1=valid, 0=null)\n#   (b) Offsets Buffer   : (N + 1) x int32 (4 byte per baris)\n#   (c) UTF-8 Data Buffer: byte mentah seluruh string digabung kontigu tanpa header PyObject!\nvalid_bits = np.packbits((~null_mask).astype(np.uint8), bitorder=\"little\")\nencoded_chunks = [b\"\" if s is None else s.encode(\"utf-8\") for s in py_col]\nlengths = np.fromiter((len(b) for b in encoded_chunks), dtype=np.int32, count=N)\noffsets = np.empty(N + 1, dtype=np.int32)\noffsets[0] = 0\nnp.cumsum(lengths, out=offsets[1:])\nutf8_data = np.frombuffer(b\"\".join(encoded_chunks), dtype=np.uint8)\n\narrow_bytes = valid_bits.nbytes + offsets.nbytes + utf8_data.nbytes\n\n# Verifikasi rekonstruksi zero-loss dari 3 buffer Arrow pada indeks acak & null\ndef read_arrow_str(idx: int) -> str | None:\n    is_valid = (valid_bits[idx >> 3] >> (idx & 7)) & 1\n    if not is_valid:\n        return None\n    start, end = int(offsets[idx]), int(offsets[idx + 1])\n    return utf8_data[start:end].tobytes().decode(\"utf-8\")\n\nsample_ok = all(read_arrow_str(i) == py_col[i] for i in [0, 1, 25, 137, 3999])\n\nprint(\"=== 1. Jejak Memori Kolom String (N = 4.000 Baris, 4% Null) ===\")\nprint(f\"Python Object List (Ptr + PyUnicode) : {py_heap_bytes:>10,d} bytes\")\nprint(f\"Apache Arrow 3-Buffer Kontigu        : {arrow_bytes:>10,d} bytes \"\n      f\"(bitmap={valid_bits.nbytes}B, offsets={offsets.nbytes}B, utf8={utf8_data.nbytes}B)\")\nprint(f\"Rasio Penghematan Memori (Py/Arrow)  : {py_heap_bytes / arrow_bytes:>10.2f}x\")\nprint(f\"Verifikasi Baca Balik Zero-Loss      : {sample_ok}\")\n\n# -----------------------------------------------------------------------------\n# 2) Simulasi Parquet Zone-Map: Eager Full Scan vs Projection & Predicate Pushdown\n# -----------------------------------------------------------------------------\nn_groups = 20\nrows_per_group = 5000\ncol_widths_bytes = {\n    \"day_idx\": 4, \"amount_idr\": 8, \"fee_bps\": 4, \"merchant_id\": 14,\n    \"user_agent\": 64, \"raw_payload_json\": 220, \"ip_trace\": 32, \"device_fp\": 48,\n}\nrow_width_all = sum(col_widths_bytes.values())\n\n# Bangun metadata Zone Map (min, max) untuk 20 Row Group terpartisi kronologis hari 1..20\nzone_maps = [\n    {\"rg\": g, \"min_day\": g + 1, \"max_day\": g + 1, \"rows\": rows_per_group}\n    for g in range(n_groups)\n]\n\n# Query target: pilih 3 kolom saja (\"day_idx\", \"amount_idr\", \"fee_bps\") untuk hari 18..20\nneeded_cols = [\"day_idx\", \"amount_idr\", \"fee_bps\"]\nproj_width = sum(col_widths_bytes[c] for c in needed_cols)\npred_lo, pred_hi = 18, 20\n\nbytes_eager = n_groups * rows_per_group * row_width_all\nbytes_proj_only = n_groups * rows_per_group * proj_width\nsurviving_rgs = [\n    zm for zm in zone_maps if not (zm[\"max_day\"] < pred_lo or zm[\"min_day\"] > pred_hi)\n]\nbytes_proj_pred = len(surviving_rgs) * rows_per_group * proj_width\n\nprint(\"\\n=== 2. Audit I/O Parquet (20 Row Groups x 5.000 Baris, 8 Kolom) ===\")\nprint(f\"Eager Full Scan (Pandas read_parquet)  : {bytes_eager / 1e6:7.2f} MB | Row Groups dibaca: {n_groups:2d}/20\")\nprint(f\"Projection Pushdown (3/8 kolom)        : {bytes_proj_only / 1e6:7.2f} MB | Penghematan I/O: {100*(1 - bytes_proj_only/bytes_eager):5.1f}%\")\nprint(f\"Projection + Predicate Pushdown (h18-20): {bytes_proj_pred / 1e6:7.2f} MB | Row Groups dibaca: {len(surviving_rgs):2d}/20\")\nprint(f\"Reduksi Total I/O Disk (Lazy Pushdown) : {100*(1 - bytes_proj_pred/bytes_eager):5.2f}% ({bytes_eager / bytes_proj_pred:.1f}x lebih sedikit byte!)\")",
          "expectedOutput": "=== 1. Jejak Memori Kolom String (N = 4.000 Baris, 4% Null) ===\nPython Object List (Ptr + PyUnicode) :    244,248 bytes\nApache Arrow 3-Buffer Kontigu        :     70,264 bytes (bitmap=500B, offsets=16004B, utf8=53760B)\nRasio Penghematan Memori (Py/Arrow)  :       3.48x\nVerifikasi Baca Balik Zero-Loss      : True\n\n=== 2. Audit I/O Parquet (20 Row Groups x 5.000 Baris, 8 Kolom) ===\nEager Full Scan (Pandas read_parquet)  :   39.40 MB | Row Groups dibaca: 20/20\nProjection Pushdown (3/8 kolom)        :    1.60 MB | Penghematan I/O:  95.9%\nProjection + Predicate Pushdown (h18-20):    0.24 MB | Row Groups dibaca:  3/20\nReduksi Total I/O Disk (Lazy Pushdown) : 99.39% (164.2x lebih sedikit byte!)",
