          "id": "code-ml-25-1-ch25_1_sklearn",
          "title": "Kesetaraan Numerik: Row-Wise .apply(axis=1) vs Vectorized Columnar vs SQL Pushdown -> HistGBDT",
          "language": "python",
          "filename": "25_1_row_apply_vs_vectorized_sql_histgbdt.py",
          "code": "import sqlite3\nimport numpy as np\nimport pandas as pd\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import roc_auc_score\n\nrng = np.random.default_rng(252)\n\n# Bangkitkan 1.500 transaksi pembayaran (40 merchant, 3 kanal) untuk uji kesetaraan fitur 3 mesin\nn_rows = 1500\ndf = pd.DataFrame({\n    \"tx_id\": np.arange(n_rows, dtype=np.int32),\n    \"merchant_id\": rng.integers(0, 40, size=n_rows, dtype=np.int32),\n    \"day\": rng.integers(1, 31, size=n_rows, dtype=np.int32),\n    \"amount\": np.round(rng.lognormal(mean=11.5, sigma=0.75, size=n_rows), 2),\n    \"is_night\": rng.integers(0, 2, size=n_rows, dtype=np.int8),\n    \"chargeback\": np.zeros(n_rows, dtype=np.int8),\n})\n# Sinyal risiko realistis: transaksi besar + malam hari + merchant berisiko\nrisk_logit = -3.4 + 0.0000045 * df[\"amount\"].to_numpy() + 1.15 * df[\"is_night\"].to_numpy() + 0.045 * (df[\"merchant_id\"].to_numpy() % 10)\nprobs = 1.0 / (1.0 + np.exp(-risk_logit))\ndf[\"chargeback\"] = (rng.uniform(size=n_rows) < probs).astype(np.int8)\n\n# -----------------------------------------------------------------------------\n# Jalur A: Anti-Pattern Row-Wise Python Loop (.apply axis=1) + Eager Grouping\n# -----------------------------------------------------------------------------\ncallback_count = 0\ndef row_risk_score(row):\n    global callback_count\n    callback_count += 1\n    return float(np.log1p(row[\"amount\"]) * (1.25 if row[\"is_night\"] == 1 else 1.0))\n\ndf_recent_a = df[df[\"day\"] >= 16].copy()\ndf_recent_a[\"weighted_log_amt\"] = df_recent_a.apply(row_risk_score, axis=1)\nagg_a = (\n    df_recent_a.groupby(\"merchant_id\", as_index=False)\n    .agg(tx_cnt=(\"tx_id\", \"count\"), mean_wlog=(\"weighted_log_amt\", \"mean\"), cb_rate=(\"chargeback\", \"mean\"))\n    .sort_values(\"merchant_id\")\n    .reset_index(drop=True)\n)\n\n# -----------------------------------------------------------------------------\n# Jalur B: Vectorized Columnar Expression (Pola Ekspresi Polars / NumPy)\n# -----------------------------------------------------------------------------\nmask_recent = df[\"day\"].to_numpy() >= 16\namt_v = df[\"amount\"].to_numpy()[mask_recent]\nnight_v = df[\"is_night\"].to_numpy()[mask_recent]\nwlog_v = np.log1p(amt_v) * np.where(night_v == 1, 1.25, 1.0)\ndf_recent_b = pd.DataFrame({\n    \"merchant_id\": df[\"merchant_id\"].to_numpy()[mask_recent],\n    \"tx_id\": df[\"tx_id\"].to_numpy()[mask_recent],\n    \"weighted_log_amt\": wlog_v,\n    \"chargeback\": df[\"chargeback\"].to_numpy()[mask_recent],\n})\nagg_b = (\n    df_recent_b.groupby(\"merchant_id\", as_index=False)\n    .agg(tx_cnt=(\"tx_id\", \"count\"), mean_wlog=(\"weighted_log_amt\", \"mean\"), cb_rate=(\"chargeback\", \"mean\"))\n    .sort_values(\"merchant_id\")\n    .reset_index(drop=True)\n)\n\n# -----------------------------------------------------------------------------\n# Jalur C: Declarative SQL Pushdown (Pola DuckDB SQL -> Materialisasi Fitur Akhir)\n# -----------------------------------------------------------------------------\ncon = sqlite3.connect(\":memory:\")\ndf[[\"tx_id\", \"merchant_id\", \"day\", \"amount\", \"is_night\", \"chargeback\"]].to_sql(\"tx\", con, index=False)\nsql_query = \"\"\"\nSELECT\n    merchant_id,\n    COUNT(tx_id) AS tx_cnt,\n    AVG(LN(1.0 + amount) * CASE WHEN is_night = 1 THEN 1.25 ELSE 1.0 END) AS mean_wlog,\n    AVG(CAST(chargeback AS REAL)) AS cb_rate\nFROM tx\nWHERE day >= 16\nGROUP BY merchant_id\nORDER BY merchant_id\n\"\"\"\nagg_c = pd.read_sql_query(sql_query, con)\ncon.close()\n\nmax_diff_ab = float(np.max(np.abs(agg_a[\"mean_wlog\"].to_numpy() - agg_b[\"mean_wlog\"].to_numpy())))\nmax_diff_ac = float(np.max(np.abs(agg_a[\"mean_wlog\"].to_numpy() - agg_c[\"mean_wlog\"].to_numpy())))\n\n# Uji fitur akhir langsung ke Scikit-Learn HistGradientBoostingClassifier (split temporal ketat!)\ntrain_df = df[df[\"day\"] <= 22].copy()\ntest_df = df[df[\"day\"] > 22].copy()\nfor part in (train_df, test_df):\n    part[\"wlog_amt\"] = np.log1p(part[\"amount\"].to_numpy()) * np.where(part[\"is_night\"].to_numpy() == 1, 1.25, 1.0)\n\nfeat_cols = [\"amount\", \"is_night\", \"wlog_amt\", \"merchant_id\"]\nclf = HistGradientBoostingClassifier(max_depth=4, max_iter=60, random_state=42)\nclf.fit(train_df[feat_cols], train_df[\"chargeback\"])\nauc_test = roc_auc_score(test_df[\"chargeback\"], clf.predict_proba(test_df[feat_cols])[:, 1])\n\nprint(\"=== Verifikasi Kesetaraan Numerik 3 Mesin Tabular (Row-Apply vs Vectorized vs SQL Pushdown) ===\")\nprint(f\"Baris pasca-filter (day >= 16)         : {len(df_recent_a)} baris -> {len(agg_a)} merchant\")\nprint(f\"Jumlah Python callback pada .apply()   : {callback_count} panggilan interpreter (Vectorized/SQL = 0!)\")\nprint(f\"Max |Jalur A (apply) - Jalur B (vec)|  : {max_diff_ab:.2e}\")\nprint(f\"Max |Jalur A (apply) - Jalur C (SQL)|  : {max_diff_ac:.2e}\")\nprint(f\"HistGBDT Temporal Test ROC-AUC (h23-30): {auc_test:.4f}\")",
          "expectedOutput": "=== Verifikasi Kesetaraan Numerik 3 Mesin Tabular (Row-Apply vs Vectorized vs SQL Pushdown) ===\nBaris pasca-filter (day >= 16)         : 711 baris -> 40 merchant\nJumlah Python callback pada .apply()   : 711 panggilan interpreter (Vectorized/SQL = 0!)\nMax |Jalur A (apply) - Jalur B (vec)|  : 0.00e+00\nMax |Jalur A (apply) - Jalur C (SQL)|  : 0.00e+00\nHistGBDT Temporal Test ROC-AUC (h23-30): 0.7092",
