          "code": "import numpy as np\nimport pandas as pd\n\n# -----------------------------------------------------------------------------\n# 1) Audit Eksak Amplifikasi Memori per Tipe Data pada Tabel 20.000 Baris\n# -----------------------------------------------------------------------------\nrng = np.random.default_rng(253)\nn_audit = 20_000\ncities = np.array([\"Jakarta\", \"Surabaya\", \"Bandung\", \"Medan\", \"Makassar\", \"Semarang\"])\ntiers = np.array([\"BRONZE\", \"SILVER\", \"GOLD\", \"PLATINUM\"])\n\ndf_naive = pd.DataFrame({\n    \"amount_f64\": rng.uniform(10_000, 5_000_000, size=n_audit).astype(np.float64),\n    \"qty_i64\": rng.integers(1, 50, size=n_audit, dtype=np.int64),\n    \"flag_i64\": rng.integers(0, 2, size=n_audit, dtype=np.int64),\n    \"city_obj\": pd.Series(rng.choice(cities, size=n_audit), dtype=object),\n    \"tier_obj\": pd.Series(rng.choice(tiers, size=n_audit), dtype=object),\n})\n\ndf_opt = pd.DataFrame({\n    \"amount_f32\": df_naive[\"amount_f64\"].astype(np.float32),\n    \"qty_i16\": df_naive[\"qty_i64\"].astype(np.int16),\n    \"flag_i8\": df_naive[\"flag_i64\"].astype(np.int8),\n    # Dictionary-encoded categorical (setara Arrow DictionaryArray / Polars Categorical)\n    \"city_cat\": pd.Categorical(df_naive[\"city_obj\"]),\n    \"tier_cat\": pd.Categorical(df_naive[\"tier_obj\"]),\n})\n\nmem_naive = int(df_naive.memory_usage(deep=True).sum())\nmem_opt = int(df_opt.memory_usage(deep=True).sum())\n\nprint(\"=== 1. Audit RAM Deep Memory Usage (20.000 Baris, 5 Kolom Campuran) ===\")\nprint(f\"Skema Pandas Naif (float64/int64/object)       : {mem_naive / 1e6:7.3f} MB\")\nprint(f\"Skema Columnar Ketat (f32/i16/i8/Categorical)  : {mem_opt / 1e6:7.3f} MB\")\nprint(f\"Rasio Pengurangan Footprint RAM                : {mem_naive / mem_opt:7.2f}x lebih hemat\")\n\n# -----------------------------------------------------------------------------\n# 2) Kalkulator Kapasitas RAM Produksi: 50 GB Parquet pada Laptop / Container 16 GB\n# -----------------------------------------------------------------------------\nparquet_gb = 50.0\nparquet_compression_ratio = 3.6  # Rasio dekompresi tipikal Parquet Snappy -> in-memory datar\ntotal_cols = 120\nselected_cols = 10\nrow_group_survival = 0.15        # Filter tanggal / segmen menyisakan 15% Row Groups\neager_copy_factor = 2.4          # Pandas chaining menciptakan 2-3 salinan DataFrame sementara\nobject_string_overhead = 1.65    # Amplifikasi pointer PyUnicode pada kolom teks Pandas klasik\nstreaming_batch_gb = 0.65        # Buffer morsel streaming Polars / DuckDB out-of-core\n\nuncompressed_all_gb = parquet_gb * parquet_compression_ratio\nram_pandas_eager = uncompressed_all_gb * object_string_overhead * eager_copy_factor\nram_polars_lazy_inmem = uncompressed_all_gb * (selected_cols / total_cols) * row_group_survival * 1.25\nram_duckdb_polars_stream = min(ram_polars_lazy_inmem, streaming_batch_gb * 2.5)\nnode_ram_gb = 16.0\n\nprint(\"\\n=== 2. Simulasi Anggaran RAM Node 16 GB untuk Dataset 50 GB Parquet (120 Kolom) ===\")\nprint(f\"Ukuran Data Tak-Terkompresi Penuh (120 kol)    : {uncompressed_all_gb:7.2f} GB\")\nprint(f\"Pandas Eager (read_parquet + copy + object)    : {ram_pandas_eager:7.2f} GB -> {'OOM CRASH!' if ram_pandas_eager > node_ram_gb else 'AMAN'}\")\nprint(f\"Polars Lazy (10/120 kol + 15% RG pushdown)     : {ram_polars_lazy_inmem:7.2f} GB -> {'OOM CRASH!' if ram_polars_lazy_inmem > node_ram_gb else 'AMAN DI 16 GB!'}\")\nprint(f\"Polars Streaming / DuckDB Out-of-Core          : {ram_duckdb_polars_stream:7.2f} GB -> {'OOM CRASH!' if ram_duckdb_polars_stream > node_ram_gb else 'AMAN KONSTAN!'}\")",
