          "starterCode": "import numpy as np\n\ndef arrow_and_pushdown_budget(strings, col_widths, needed_cols, rg_bounds, pred_lo, pred_hi) -> tuple[int, int, float]:\n    # TODO: hitung total byte 3-buffer Arrow -> hitung surviving Row Groups -> hitung % reduksi I/O total\n    pass\n\ns_in = [\"JKT_01\", \"SBY_02\", None, \"BDG_03\", \"MDN_04\", \"JKT_05\", None, \"SBY_06\", \"BDG_07\"]\ncw = {\"day\": 4, \"amt\": 8, \"cat\": 12, \"payload\": 176}\nrgs = [(1, 5), (6, 10), (11, 15), (16, 20), (21, 25)]\nprint(arrow_and_pushdown_budget(s_in, cw, [\"day\", \"amt\"], rgs, 14, 19))",
