          "id": "code-ml-25-2-ch25_2_sklearn",
          "title": "Scikit-Learn 1.9: ColumnTransformer, set_output('pandas'), TargetEncoder & SLEP006 Metadata Routing",
          "language": "python",
          "filename": "25_2_sklearn_columntransformer_metadata_routing.py",
          "code": "import numpy as np\nimport pandas as pd\nimport sklearn\nfrom sklearn.compose import ColumnTransformer, make_column_selector\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import make_scorer, roc_auc_score\nfrom sklearn.model_selection import GroupKFold, cross_val_score\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler, TargetEncoder\n\nrng = np.random.default_rng(2522)\nn = 480\n\n# Dataset kredit heterogen (numerik ber-NaN, kategorial kardinalitas rendah & menengah, bobot transaksi, grup peminjam)\nregions = rng.choice([\"JKT\", \"BDG\", \"SBY\", \"MDN\", \"RARE_CITY_1\", \"RARE_CITY_2\"], size=n, p=[0.35, 0.25, 0.20, 0.14, 0.03, 0.03])\nmerchants = rng.choice([f\"M{i:02d}\" for i in range(25)], size=n)\nincome = rng.lognormal(mean=2.3, sigma=0.55, size=n)\ndti = np.clip(rng.normal(0.34, 0.14, size=n), 0.02, 0.95)\nincome[rng.choice(n, size=24, replace=False)] = np.nan\n\n# Grup peminjam (160 nasabah x 3 pinjaman) untuk GroupKFold bebas leakage antar-nasabah\ngroups = np.repeat(np.arange(160), 3)\nsample_weight = np.round(rng.uniform(0.6, 3.0, size=n), 2)\n\n# Target default dengan sinyal kuat dari DTI, income, region, dan subset merchant\nmerch_risk = np.array([0.9 if int(m[1:]) < 5 else -0.2 for m in merchants])\nlogit = -1.2 + 3.4 * dti - 0.12 * np.nan_to_num(income, nan=10.0) + merch_risk + np.where(regions == \"MDN\", 0.5, 0.0)\ny = (rng.uniform(size=n) < 1.0 / (1.0 + np.exp(-logit))).astype(int)\n\nX_df = pd.DataFrame({\n    \"income_jt\": income,\n    \"debt_to_income\": dti,\n    \"region\": regions,\n    \"merchant_code\": merchants,\n})\n\n# -----------------------------------------------------------------------------\n# 1) Pipeline Produksi Scikit-Learn 1.6+: ColumnTransformer + set_output(\"pandas\") + TargetEncoder\n# -----------------------------------------------------------------------------\nnum_pipe = Pipeline([\n    (\"imputer\", SimpleImputer(strategy=\"median\", add_indicator=True)),\n    (\"scaler\", StandardScaler()),\n])\nlow_card_pipe = Pipeline([\n    (\"imputer\", SimpleImputer(strategy=\"constant\", fill_value=\"MISSING\")),\n    # min_frequency menggabungkan kategori langka otomatis; handle_unknown=\"ignore\" kebal kategori baru!\n    (\"ohe\", OneHotEncoder(handle_unknown=\"ignore\", min_frequency=25, sparse_output=False)),\n])\nhigh_card_pipe = Pipeline([\n    (\"imputer\", SimpleImputer(strategy=\"constant\", fill_value=\"MISSING\")),\n    # TargetEncoder bawaan Sklearn 1.3+ memakai internal cross-fitting agar bebas target leakage!\n    (\"te\", TargetEncoder(smooth=\"auto\", cv=4, random_state=42)),\n])\n\npreprocessor = ColumnTransformer(\n    transformers=[\n        (\"num\", num_pipe, make_column_selector(dtype_include=np.number)),\n        (\"low_cat\", low_card_pipe, [\"region\"]),\n        (\"high_cat\", high_card_pipe, [\"merchant_code\"]),\n    ],\n    remainder=\"drop\",\n    verbose_feature_names_out=True,\n).set_output(transform=\"pandas\")\n\nfull_pipe = Pipeline([\n    (\"prep\", preprocessor),\n    (\"clf\", LogisticRegression(C=1.0, max_iter=500, random_state=42)),\n]).fit(X_df, y)\n\n# Transformasi keluar tetap berupa pandas.DataFrame lengkap dengan nama fitur eksplisit!\nX_transformed = full_pipe.named_steps[\"prep\"].transform(X_df.iloc[:3])\n\n# -----------------------------------------------------------------------------\n# 2) SLEP006 Metadata Routing: Meneruskan sample_weight & groups ke GroupKFold + Weighted Scorer\n# -----------------------------------------------------------------------------\nwith sklearn.config_context(enable_metadata_routing=True):\n    # Wajib deklarasi eksplisit: scaler TIDAK memakai bobot, classifier & scorer MEMAKAI bobot!\n    routed_num = Pipeline([\n        (\"imputer\", SimpleImputer(strategy=\"median\")),\n        (\"scaler\", StandardScaler().set_fit_request(sample_weight=False)),\n    ])\n    routed_prep = ColumnTransformer([\n        (\"num\", routed_num, make_column_selector(dtype_include=np.number)),\n        (\"cat\", OneHotEncoder(handle_unknown=\"ignore\", min_frequency=25, sparse_output=False), [\"region\"]),\n    ]).set_output(transform=\"pandas\")\n\n    routed_clf = LogisticRegression(C=1.0, max_iter=500, random_state=42).set_fit_request(sample_weight=True)\n    weighted_auc = make_scorer(roc_auc_score, response_method=\"predict_proba\").set_score_request(sample_weight=True)\n    routed_pipe = Pipeline([(\"prep\", routed_prep), (\"clf\", routed_clf)])\n\n    cv_scores = cross_val_score(\n        routed_pipe,\n        X_df[[\"income_jt\", \"debt_to_income\", \"region\"]],\n        y,\n        cv=GroupKFold(n_splits=4),\n        scoring=weighted_auc,\n        params={\"sample_weight\": sample_weight, \"groups\": groups},\n    )\n\nprint(\"=== Scikit-Learn 1.9 Production Pipeline: ColumnTransformer + set_output + Metadata Routing ===\")\nprint(f\"Tipe Output Preprocessor     : {type(X_transformed).__name__} (shape={X_transformed.shape})\")\nprint(f\"Daftar Fitur Terpelihara ({len(X_transformed.columns)}): {list(X_transformed.columns)}\")\nprint(f\"Weighted GroupKFold ROC-AUC  : {np.round(cv_scores, 4)} | Mean = {cv_scores.mean():.4f}\")\n\n# Uji batch serving berisi kategori tak dikenal & urutan kolom terbalik\nX_serve_new = pd.DataFrame({\n    \"merchant_code\": [\"M99_UNSEEN\", \"M01\"],\n    \"region\": [\"IKN_BARU\", \"JKT\"],\n    \"debt_to_income\": [0.45, 0.22],\n    \"income_jt\": [np.nan, 15.0],\n})\nserve_proba = full_pipe.predict_proba(X_serve_new)[:, 1]\nprint(f\"Probabilitas Serving (Unseen + Reordered + NaN): {np.round(serve_proba, 4)}  <-- Zero Crash!\")",
          "expectedOutput": "=== Scikit-Learn 1.9 Production Pipeline: ColumnTransformer + set_output + Metadata Routing ===\nTipe Output Preprocessor     : DataFrame (shape=(3, 9))\nDaftar Fitur Terpelihara (9): ['num__income_jt', 'num__debt_to_income', 'num__missingindicator_income_jt', 'low_cat__region_BDG', 'low_cat__region_JKT', 'low_cat__region_MDN', 'low_cat__region_SBY', 'low_cat__region_infrequent_sklearn', 'high_cat__merchant_code']\nWeighted GroupKFold ROC-AUC  : [0.632  0.7789 0.7396 0.7518] | Mean = 0.7256\nProbabilitas Serving (Unseen + Reordered + NaN): [0.1069 0.0957]  <-- Zero Crash!",
          "actualOutput": "=== Scikit-Learn 1.9 Production Pipeline: ColumnTransformer + set_output + Metadata Routing ===\nTipe Output Preprocessor     : DataFrame (shape=(3, 9))\nDaftar Fitur Terpelihara (9): ['num__income_jt', 'num__debt_to_income', 'num__missingindicator_income_jt', 'low_cat__region_BDG', 'low_cat__region_JKT', 'low_cat__region_MDN', 'low_cat__region_SBY', 'low_cat__region_infrequent_sklearn', 'high_cat__merchant_code']\nWeighted GroupKFold ROC-AUC  : [0.632  0.7789 0.7396 0.7518] | Mean = 0.7256\nProbabilitas Serving (Unseen + Reordered + NaN): [0.1069 0.0957]  <-- Zero Crash!",
          "explanation": "Merangkai pipeline kredit multi-cabang (SimpleImputer add_indicator, StandardScaler, OneHotEncoder min_frequency+ignore, TargetEncoder cross-fit) dengan set_output('pandas') serta SLEP006 Metadata Routing meneruskan sample_weight & groups ke GroupKFold dan weighted ROC-AUC.",
