          "filename": "25_2_pandas3_selector_routing_permutation_audit.py",
          "code": "import numpy as np\nimport pandas as pd\nimport sklearn\nfrom sklearn.compose import ColumnTransformer, make_column_selector\nfrom sklearn.exceptions import UnsetMetadataPassedError\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler\n\n# -----------------------------------------------------------------------------\n# Audit 1: Jebakan Senyap make_column_selector(dtype_include=\"object\") pada Categorical & StringDtype!\n# -----------------------------------------------------------------------------\ndf_p3 = pd.DataFrame({\n    \"amount\": [100.0, 250.0, 400.0, 150.0],\n    \"channel\": pd.Series([\"APP\", \"WEB\", \"APP\", \"STORE\"], dtype=\"string\"),\n    \"tier\": pd.Categorical([\"GOLD\", \"SILVER\", \"GOLD\", \"BRONZE\"]),\n})\n\nsel_legacy_obj = make_column_selector(dtype_include=\"object\")(df_p3)\nsel_modern_safe = make_column_selector(dtype_exclude=np.number)(df_p3)\nsel_explicit_str = make_column_selector(dtype_include=[\"object\", \"string\", \"category\"])(df_p3)\n\nprint(\"=== 1. Audit Column Selector pada StringDtype & Categorical (Pandas 2.x/3.0) ===\")\nprint(f\"Dtypes aktual DataFrame          : { {k: str(v) for k, v in df_p3.dtypes.items()} }\")\nprint(f\"Selector lama dtype='object'     : {sel_legacy_obj}  <-- BAHAYA! Kolom 'channel'/'tier' TERLEWAT!\")\nprint(f\"Selector aman dtype_exclude=num  : {sel_modern_safe}\")\nprint(f\"Selector aman [object,str,cat]   : {sel_explicit_str}\")\n\n# -----------------------------------------------------------------------------\n# Audit 2: Verifikasi Proteksi UnsetMetadataPassedError (SLEP006 Metadata Routing)\n# -----------------------------------------------------------------------------\nX_toy = np.array([[1.0, 2.0], [2.0, 1.0], [3.0, 4.0], [4.0, 3.0]])\ny_toy = np.array([0, 0, 1, 1])\nw_toy = np.array([1.0, 2.0, 1.0, 3.0])\n\ncaught_unset_err = False\nwith sklearn.config_context(enable_metadata_routing=True):\n    # Sengaja LUPA mendeklarasikan set_fit_request pada StandardScaler\n    pipe_unset = Pipeline([\n        (\"sc\", StandardScaler()),\n        (\"lr\", LogisticRegression().set_fit_request(sample_weight=True)),\n    ])\n    try:\n        pipe_unset.fit(X_toy, y_toy, sample_weight=w_toy)\n    except UnsetMetadataPassedError:\n        caught_unset_err = True\n\nprint(\"\\n=== 2. Audit Proteksi SLEP006 Metadata Routing ===\")\nprint(f\"UnsetMetadataPassedError tertangkap otomatis bila deklarasi lupa: {caught_unset_err}\")\n\n# -----------------------------------------------------------------------------\n# Audit 3: Invariansi Urutan Kolom & Ekstraksi Koefisien Bernama (get_feature_names_out)\n# -----------------------------------------------------------------------------\nct = ColumnTransformer([\n    (\"num\", StandardScaler(), make_column_selector(dtype_include=np.number)),\n    (\"cat\", OneHotEncoder(handle_unknown=\"ignore\", sparse_output=False), make_column_selector(dtype_exclude=np.number)),\n]).set_output(transform=\"pandas\")\n\npipe_named = Pipeline([(\"ct\", ct), (\"lr\", LogisticRegression(random_state=42))])\npipe_named.fit(df_p3, np.array([0, 1, 0, 1]))\n\np_orig = pipe_named.predict_proba(df_p3)[:, 1]\np_shuf = pipe_named.predict_proba(df_p3[[\"tier\", \"channel\", \"amount\"]])[:, 1]\ncoef_map = {\n    name: round(float(val), 4)\n    for name, val in zip(pipe_named.named_steps[\"ct\"].get_feature_names_out(), pipe_named.named_steps[\"lr\"].coef_[0])\n}\n\nprint(\"\\n=== 3. Audit Paritas Serving Saat Kolom Diacak & Pemetaan Koefisien ===\")\nprint(f\"Max |proba(orig) - proba(shuffled_cols)| : {float(np.max(np.abs(p_orig - p_shuf))):.2e}\")\nprint(f\"Peta Bobot Model Bernama                 : {coef_map}\")",
          "expectedOutput": "=== 1. Audit Column Selector pada StringDtype & Categorical (Pandas 2.x/3.0) ===\nDtypes aktual DataFrame          : {'amount': 'float64', 'channel': 'string', 'tier': 'category'}\nSelector lama dtype='object'     : []  <-- BAHAYA! Kolom 'channel'/'tier' TERLEWAT!\nSelector aman dtype_exclude=num  : ['channel', 'tier']\nSelector aman [object,str,cat]   : ['channel', 'tier']\n\n=== 2. Audit Proteksi SLEP006 Metadata Routing ===\nUnsetMetadataPassedError tertangkap otomatis bila deklarasi lupa: True\n\n=== 3. Audit Paritas Serving Saat Kolom Diacak & Pemetaan Koefisien ===\nMax |proba(orig) - proba(shuffled_cols)| : 0.00e+00\nPeta Bobot Model Bernama                 : {'num__amount': -0.1439, 'cat__channel_APP': -0.5794, 'cat__channel_STORE': 0.2806, 'cat__channel_WEB': 0.299, 'cat__tier_BRONZE': 0.2806, 'cat__tier_GOLD': -0.5794, 'cat__tier_SILVER': 0.299}",
