          "solution": "```python\nimport numpy as np\nimport pandas as pd\nfrom sklearn.compose import ColumnTransformer, make_column_selector\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler\n\ndef audit_columntransformer_skew(df_train: pd.DataFrame, df_serve: pd.DataFrame) -> tuple[int, float, float]:\n    ct = ColumnTransformer([\n        ('num', Pipeline([('imp', SimpleImputer(strategy='median')), ('sc', StandardScaler())]),\n         make_column_selector(dtype_include=np.number)),\n        ('cat', OneHotEncoder(handle_unknown='ignore', sparse_output=False),\n         make_column_selector(dtype_exclude=np.number)),\n    ]).set_output(transform='pandas')\n    ct.fit(df_train)\n    Z_orig = ct.transform(df_serve)\n    Z_rev = ct.transform(df_serve[list(reversed(df_serve.columns))])\n    n_out_cols = int(Z_orig.shape[1])\n    max_perm_diff = float(np.max(np.abs(Z_orig.to_numpy() - Z_rev.to_numpy())))\n    cat_cols = [c for c in Z_orig.columns if c.startswith('cat__')]\n    unseen_row_ohe_sum = float(Z_orig.loc[Z_orig.index[0], cat_cols].sum())\n    return (n_out_cols, round(max_perm_diff, 10), round(unseen_row_ohe_sum, 4))\n```"
