          "code": "import numpy as np\nimport pandas as pd\nfrom sklearn.base import BaseEstimator, OneToOneFeatureMixin, TransformerMixin\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import GradientBoostingClassifier\nfrom sklearn.frozen import FrozenEstimator\nfrom sklearn.metrics import brier_score_loss, make_scorer\nfrom sklearn.model_selection import TunedThresholdClassifierCV, train_test_split\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.utils.estimator_checks import check_estimator\nfrom sklearn.utils.validation import check_is_fitted, validate_data\n\n# -----------------------------------------------------------------------------\n# 1) Custom Transformer Produksi: Lolos 100% Kontrak check_estimator() Sklearn 1.9!\n# -----------------------------------------------------------------------------\nclass QuantileWinsorizer(OneToOneFeatureMixin, TransformerMixin, BaseEstimator):\n    \"\"\"Memangkas ekor outlier ke kuantil [lower_q, upper_q] yang dipelajari HANYA di fit().\"\"\"\n    def __init__(self, lower_q: float = 0.02, upper_q: float = 0.98):\n        self.lower_q = lower_q\n        self.upper_q = upper_q\n\n    def fit(self, X, y=None):\n        X_arr = validate_data(self, X, ensure_2d=True, dtype=\"numeric\")\n        if not (0.0 <= self.lower_q < self.upper_q <= 1.0):\n            raise ValueError(\"Wajib memenuhi 0.0 <= lower_q < upper_q <= 1.0\")\n        self.lower_ = np.quantile(X_arr, self.lower_q, axis=0)\n        self.upper_ = np.quantile(X_arr, self.upper_q, axis=0)\n        return self\n\n    def transform(self, X):\n        check_is_fitted(self, [\"lower_\", \"upper_\"])\n        X_arr = validate_data(self, X, reset=False, ensure_2d=True, dtype=\"numeric\")\n        return np.clip(X_arr, self.lower_, self.upper_)\n\n# Verifikasi otomatis seluruh kontrak Scikit-Learn API (clone, pickling, NaN, single-row, dsb.)\ncheck_results = check_estimator(QuantileWinsorizer(), on_fail=\"raise\")\nprint(\"=== 1. Audit Kontrak Resmi Scikit-Learn check_estimator() ===\")\nprint(f\"QuantileWinsorizer lulus 100% check_estimator() (on_fail='raise'): PASSED!\")\n\n# -----------------------------------------------------------------------------\n# 2) FrozenEstimator (Scikit-Learn 1.6+): Kalibrasi & Threshold Tuning Tanpa Retrain!\n# -----------------------------------------------------------------------------\nX_raw, y_raw = make_classification(\n    n_samples=1200, n_features=8, n_informative=5, weights=[0.84, 0.16],\n    flip_y=0.04, class_sep=0.85, random_state=2532,\n)\nfeat_names = [f\"feat_{i}\" for i in range(X_raw.shape[1])]\nX_df = pd.DataFrame(X_raw, columns=feat_names)\n\n# Bagi ketat menjadi 3 partisi terpisah: Train (60%), Calibration/Threshold (20%), Test (20%)\nX_tr, X_tmp, y_tr, y_tmp = train_test_split(X_df, y_raw, test_size=0.40, stratify=y_raw, random_state=42)\nX_cal, X_te, y_cal, y_te = train_test_split(X_tmp, y_tmp, test_size=0.50, stratify=y_tmp, random_state=42)\n\nbase_pipe = Pipeline([\n    (\"winsor\", QuantileWinsorizer(lower_q=0.02, upper_q=0.98).set_output(transform=\"pandas\")),\n    (\"gbdt\", GradientBoostingClassifier(n_estimators=75, max_depth=4, learning_rate=0.15, random_state=42)),\n]).fit(X_tr, y_tr)\n\n# Kunci snapshot prediksi mentah base_pipe untuk membuktikan bobot tidak tersentuh\nraw_cal_snapshot = base_pipe.predict_proba(X_te)[:, 1].copy()\n\n# Bungkus dengan FrozenEstimator -> .fit() menjadi NO-OP murni!\nfrozen_base = FrozenEstimator(base_pipe)\ncal_model = CalibratedClassifierCV(frozen_base, method=\"sigmoid\").fit(X_cal, y_cal)\n\n# Optimasi ambang keputusan asimetris (FN fraud = -10, FP blokir = -1) di atas model terkalibrasi beku!\ndef fraud_business_utility(y_true, y_pred):\n    fp = np.sum((y_true == 0) & (y_pred == 1))\n    fn = np.sum((y_true == 1) & (y_pred == 0))\n    return float(-(1.0 * fp + 10.0 * fn) / len(y_true))\n\nutility_scorer = make_scorer(fraud_business_utility)\ntuned_clf = TunedThresholdClassifierCV(\n    FrozenEstimator(cal_model), scoring=utility_scorer, cv=3, thresholds=40, response_method=\"predict_proba\"\n).fit(X_cal, y_cal)\n\n# Verifikasi nol perubahan pada model dasar + peningkatan metrik uji\nweights_untouched = bool(np.array_equal(raw_cal_snapshot, base_pipe.predict_proba(X_te)[:, 1]))\np_raw_te = base_pipe.predict_proba(X_te)[:, 1]\np_cal_te = cal_model.predict_proba(X_te)[:, 1]\n\ndef compute_ece(y_t, p_hat, n_bins=8):\n    bins = np.linspace(0.0, 1.0, n_bins + 1)\n    ece = 0.0\n    for b0, b1 in zip(bins[:-1], bins[1:]):\n        m = (p_hat >= b0) & (p_hat < b1 if b1 < 1.0 else p_hat <= b1)\n        if np.any(m):\n            ece += (np.sum(m) / len(y_t)) * abs(np.mean(y_t[m]) - np.mean(p_hat[m]))\n    return float(ece)\n\nutil_default_05 = fraud_business_utility(y_te, (p_cal_te >= 0.50).astype(int))\nutil_tuned = fraud_business_utility(y_te, tuned_clf.predict(X_te))\n\nprint(\"\\n=== 2. FrozenEstimator: Post-Hoc Calibration & Threshold Tuning Tanpa Retrain ===\")\nprint(f\"Model dasar 100% tidak dilatih ulang   : {weights_untouched}\")\nprint(f\"Brier Score Test (Mentah -> Terkalibrasi): {brier_score_loss(y_te, p_raw_te):.4f} -> {brier_score_loss(y_te, p_cal_te):.4f}\")\nprint(f\"ECE Test 8-Bin   (Mentah -> Terkalibrasi): {compute_ece(y_te, p_raw_te):.4f} -> {compute_ece(y_te, p_cal_te):.4f}\")\nprint(f\"Ambang Bisnis Optimal (FN=-10, FP=-1)  : tau* = {tuned_clf.best_threshold_:.4f} (teori Bayes = 1/11 = 0.0909)\")\nprint(f\"Expected Cost/Tx (tau=0.50 -> tau*)    : {-util_default_05:.4f} -> {-util_tuned:.4f} (lebih rendah = lebih hemat!)\")",
          "expectedOutput": "=== 1. Audit Kontrak Resmi Scikit-Learn check_estimator() ===\nQuantileWinsorizer lulus 100% check_estimator() (on_fail='raise'): PASSED!\n\n=== 2. FrozenEstimator: Post-Hoc Calibration & Threshold Tuning Tanpa Retrain ===\nModel dasar 100% tidak dilatih ulang   : True\nBrier Score Test (Mentah -> Terkalibrasi): 0.0773 -> 0.0740\nECE Test 8-Bin   (Mentah -> Terkalibrasi): 0.0598 -> 0.0323\nAmbang Bisnis Optimal (FN=-10, FP=-1)  : tau* = 0.3273 (teori Bayes = 1/11 = 0.0909)\nExpected Cost/Tx (tau=0.50 -> tau*)    : 0.8917 -> 0.7708 (lebih rendah = lebih hemat!)",
          "actualOutput": "=== 1. Audit Kontrak Resmi Scikit-Learn check_estimator() ===\nQuantileWinsorizer lulus 100% check_estimator() (on_fail='raise'): PASSED!\n\n=== 2. FrozenEstimator: Post-Hoc Calibration & Threshold Tuning Tanpa Retrain ===\nModel dasar 100% tidak dilatih ulang   : True\nBrier Score Test (Mentah -> Terkalibrasi): 0.0773 -> 0.0740\nECE Test 8-Bin   (Mentah -> Terkalibrasi): 0.0598 -> 0.0323\nAmbang Bisnis Optimal (FN=-10, FP=-1)  : tau* = 0.3273 (teori Bayes = 1/11 = 0.0909)\nExpected Cost/Tx (tau=0.50 -> tau*)    : 0.8917 -> 0.7708 (lebih rendah = lebih hemat!)",
