          "filename": "25_3_contract_violations_and_calibration_bias.py",
          "code": "import numpy as np\nfrom sklearn.base import BaseEstimator, TransformerMixin, clone\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.exceptions import NotFittedError\nfrom sklearn.frozen import FrozenEstimator\nfrom sklearn.metrics import brier_score_loss, log_loss\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.utils.validation import check_is_fitted\n\n# -----------------------------------------------------------------------------\n# 1) Audit 3 Bug Klasik Custom Transformer yang Menghancurkan GridSearchCV & Serving\n# -----------------------------------------------------------------------------\nclass BrokenInitMutator(TransformerMixin, BaseEstimator):\n    def __init__(self, cap=5.0):\n        # BUG 1: Memodifikasi argumen di __init__ -> langsung merusak sklearn.base.clone()!\n        self.cap = float(cap) * 2.0\n    def fit(self, X, y=None):\n        self.fitted_ = True\n        return self\n    def transform(self, X):\n        return np.clip(X, -self.cap, self.cap)\n\nclass MissingFittedGuard(TransformerMixin, BaseEstimator):\n    def __init__(self, scale=1.0):\n        self.scale = scale\n    def fit(self, X, y=None):\n        self.med_ = np.median(X, axis=0)\n        return self\n    def transform(self, X):\n        # BUG 2: Tidak memanggil check_is_fitted() -> memunculkan AttributeError mentah, bukan NotFittedError!\n        return (X - self.med_) * self.scale\n\n# Uji clone() terhadap BrokenInitMutator\nclone_failed_msg = \"\"\ntry:\n    clone(BrokenInitMutator(cap=5.0))\nexcept RuntimeError as exc:\n    clone_failed_msg = type(exc).__name__\n\n# Uji NotFittedError terhadap MissingFittedGuard\nerr_type_missing_guard = \"\"\ntry:\n    MissingFittedGuard().transform(np.ones((3, 2)))\nexcept Exception as exc:\n    err_type_missing_guard = type(exc).__name__\n\nprint(\"=== 1. Audit Kegagalan Kontrak Custom Transformer ===\")\nprint(f\"Mutasi argumen di __init__ -> clone() gagal dengan : {clone_failed_msg}\")\nprint(f\"Lupa check_is_fitted()     -> melempar             : {err_type_missing_guard} (seharusnya NotFittedError!)\")\n\n# -----------------------------------------------------------------------------\n# 2) Audit Optimism Bias: Kalibrasi di X_train (BOCOR!) vs X_cal Disjoint via FrozenEstimator\n# -----------------------------------------------------------------------------\nX, y = make_classification(\n    n_samples=1500, n_features=12, n_informative=4, n_redundant=2,\n    weights=[0.78, 0.22], flip_y=0.12, class_sep=0.75, random_state=2533,\n)\nX_tr, X_tmp, y_tr, y_tmp = train_test_split(X, y, test_size=0.45, stratify=y, random_state=42)\nX_cal, X_te, y_cal, y_te = train_test_split(X_tmp, y_tmp, test_size=0.50, stratify=y_tmp, random_state=42)\n\n# Model berkapasitas tinggi (RandomForest tanpa batas kedalaman -> hampir 100% akurat & overconfident di X_train!)\noverfit_clf = RandomForestClassifier(\n    n_estimators=60, max_depth=None, min_samples_leaf=1, random_state=42\n).fit(X_tr, y_tr)\n\n# ANTI-PATTERN: Kalibrasi Isotonic di atas X_train yang SAMA -> calibrator belajar tangga ekstrem {0, 1}!\ncal_leaky = CalibratedClassifierCV(FrozenEstimator(overfit_clf), method=\"isotonic\").fit(X_tr, y_tr)\n# PRODUCTION-SAFE: Kalibrasi Isotonic di atas X_cal yang 100% terpisah!\ncal_clean = CalibratedClassifierCV(FrozenEstimator(overfit_clf), method=\"isotonic\").fit(X_cal, y_cal)\n\np_raw = overfit_clf.predict_proba(X_te)[:, 1]\np_leaky = cal_leaky.predict_proba(X_te)[:, 1]\np_clean = cal_clean.predict_proba(X_te)[:, 1]\n\nprint(\"\\n=== 2. Audit Bahaya Kalibrasi pada X_train vs X_cal Terpisah (Held-Out Test) ===\")\nprint(f\"Mentah (RandomForest)               | Brier = {brier_score_loss(y_te, p_raw):.4f} | LogLoss = {log_loss(y_te, p_raw):.4f}\")\nprint(f\"Kalibrasi BOCOR di X_train          | Brier = {brier_score_loss(y_te, p_leaky):.4f} | LogLoss = {log_loss(y_te, p_leaky):.4f}  <-- MERUSAK KALIBRASI!\")\nprint(f\"Kalibrasi BERSIH di X_cal (Frozen)  | Brier = {brier_score_loss(y_te, p_clean):.4f} | LogLoss = {log_loss(y_te, p_clean):.4f}  <-- TERBAIK DI TEST!\")",
          "expectedOutput": "=== 1. Audit Kegagalan Kontrak Custom Transformer ===\nMutasi argumen di __init__ -> clone() gagal dengan : RuntimeError\nLupa check_is_fitted()     -> melempar             : AttributeError (seharusnya NotFittedError!)\n\n=== 2. Audit Bahaya Kalibrasi pada X_train vs X_cal Terpisah (Held-Out Test) ===\nMentah (RandomForest)               | Brier = 0.1378 | LogLoss = 0.4344\nKalibrasi BOCOR di X_train          | Brier = 0.1505 | LogLoss = 2.5852  <-- MERUSAK KALIBRASI!\nKalibrasi BERSIH di X_cal (Frozen)  | Brier = 0.1315 | LogLoss = 0.4151  <-- TERBAIK DI TEST!",
          "actualOutput": "=== 1. Audit Kegagalan Kontrak Custom Transformer ===\nMutasi argumen di __init__ -> clone() gagal dengan : RuntimeError\nLupa check_is_fitted()     -> melempar             : AttributeError (seharusnya NotFittedError!)\n\n=== 2. Audit Bahaya Kalibrasi pada X_train vs X_cal Terpisah (Held-Out Test) ===\nMentah (RandomForest)               | Brier = 0.1378 | LogLoss = 0.4344\nKalibrasi BOCOR di X_train          | Brier = 0.1505 | LogLoss = 2.5852  <-- MERUSAK KALIBRASI!\nKalibrasi BERSIH di X_cal (Frozen)  | Brier = 0.1315 | LogLoss = 0.4151  <-- TERBAIK DI TEST!",
