          "id": "code-ml-25-4-ch25_4_sklearn",
          "title": "CI/CD Test Suite: Determinisme, Permutasi Baris, Single-Row Parity, SHA-256 & No-Future-Leakage",
          "language": "python",
          "filename": "25_4_cicd_5_invariants_and_leakage_suite.py",
          "code": "import hashlib\nimport pickle\nimport numpy as np\nimport pandas as pd\nfrom sklearn.compose import ColumnTransformer, make_column_selector\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler\n\nrng = np.random.default_rng(2542)\nn = 360\n\n# Dataset temporal terurut (t=0..359) untuk menguji 5 Invarian CI/CD Pipeline sekaligus\ndf_full = pd.DataFrame({\n    \"t\": np.arange(n),\n    \"spend_idr_k\": np.round(rng.lognormal(mean=4.2, sigma=0.6, size=n), 2),\n    \"latency_ms\": np.round(rng.uniform(20.0, 220.0, size=n), 2),\n    \"channel\": rng.choice([\"APP\", \"WEB\", \"POS\"], size=n),\n})\ny_full = (\n    (df_full[\"spend_idr_k\"].to_numpy() > 75.0).astype(int)\n    ^ (rng.uniform(size=n) < 0.15)\n).astype(int)\n\n# Bangun fitur kausal (HANYA masa lalu) vs fitur bocor masa depan (center=True)\ndef add_causal_rolling(df: pd.DataFrame) -> pd.DataFrame:\n    out = df.copy()\n    out[\"roll5_spend\"] = out[\"spend_idr_k\"].rolling(window=5, min_periods=1, center=False).mean()\n    return out\n\ndef add_leaky_centered_rolling(df: pd.DataFrame) -> pd.DataFrame:\n    out = df.copy()\n    # BUG KLASIK: center=True mengintip 2 baris masa depan (t+1, t+2)!\n    out[\"roll5_spend\"] = out[\"spend_idr_k\"].rolling(window=5, min_periods=1, center=True).mean()\n    return out\n\nX_train = add_causal_rolling(df_full.iloc[:280]).drop(columns=[\"t\"])\ny_train = y_full[:280]\nX_test = add_causal_rolling(df_full.iloc[280:]).drop(columns=[\"t\"]).reset_index(drop=True)\n\npipe = Pipeline([\n    (\"prep\", ColumnTransformer([\n        (\"num\", Pipeline([(\"imp\", SimpleImputer(strategy=\"median\")), (\"sc\", StandardScaler())]),\n         make_column_selector(dtype_include=np.number)),\n        (\"cat\", OneHotEncoder(handle_unknown=\"ignore\", sparse_output=False),\n         make_column_selector(dtype_exclude=np.number)),\n    ]).set_output(transform=\"pandas\")),\n    (\"clf\", HistGradientBoostingClassifier(max_depth=4, max_iter=50, random_state=42)),\n]).fit(X_train, y_train)\n\n# -----------------------------------------------------------------------------\n# SUITE 5 INVARIAN CI/CD OTOMATIS (Sebelum Promosi Artefak ke Produksi!)\n# -----------------------------------------------------------------------------\n# Tes 1: Determinisme Berulang\np1 = pipe.predict_proba(X_test)[:, 1]\np2 = pipe.predict_proba(X_test)[:, 1]\nt1_det = float(np.max(np.abs(p1 - p2)))\n\n# Tes 2: Invariansi Permutasi Urutan Baris: Phi(Pi X) == Pi Phi(X)\nperm = rng.permutation(len(X_test))\np_perm = pipe.predict_proba(X_test.iloc[perm])[:, 1]\nt2_perm = float(np.max(np.abs(p_perm - p1[perm])))\n\n# Tes 3: Paritas Single-Row (N=1) vs Batch (N=80) (Zero Online-Offline Skew!)\np_single = np.array([pipe.predict_proba(X_test.iloc[i : i + 1])[0, 1] for i in range(len(X_test))])\nt3_single = float(np.max(np.abs(p_single - p1)))\n\n# Tes 4: Paritas Round-Trip Serialisasi & Checksum SHA-256\nblob = pickle.dumps(pipe)\npipe_reloaded = pickle.loads(blob)\np_reload = pipe_reloaded.predict_proba(X_test)[:, 1]\nt4_serial = float(np.max(np.abs(p_reload - p1)))\npred_sha256 = hashlib.sha256(np.round(p_reload, 12).tobytes()).hexdigest()[:16]\n\n# Tes 5: Uji Perturbasi Masa Depan (No-Future-Leakage Causal Test pada t0 = 50)\nt0 = 50\ndf_perturbed = df_full.copy()\ndf_perturbed.loc[t0 + 1 :, \"spend_idr_k\"] *= 99.0  # Merusak seluruh baris masa depan (t > 50)!\n\ncausal_delta = float(np.max(np.abs(\n    add_causal_rolling(df_full).loc[:t0, \"roll5_spend\"].to_numpy()\n    - add_causal_rolling(df_perturbed).loc[:t0, \"roll5_spend\"].to_numpy()\n)))\nleaky_delta = float(np.max(np.abs(\n    add_leaky_centered_rolling(df_full).loc[:t0, \"roll5_spend\"].to_numpy()\n    - add_leaky_centered_rolling(df_perturbed).loc[:t0, \"roll5_spend\"].to_numpy()\n)))\n\nprint(\"=== CI/CD Pipeline Invariance & No-Future-Leakage Test Suite ===\")\nprint(f\"[T1] Determinisme (max delta)            : {t1_det:.2e} -> {'PASS' if t1_det == 0.0 else 'FAIL'}\")\nprint(f\"[T2] Invariansi Permutasi Baris          : {t2_perm:.2e} -> {'PASS' if t2_perm < 1e-12 else 'FAIL'}\")\nprint(f\"[T3] Paritas Single-Row vs Batch (N=80)  : {t3_single:.2e} -> {'PASS' if t3_single < 1e-12 else 'FAIL'}\")\nprint(f\"[T4] Round-Trip Serialisasi (SHA={pred_sha256}): {t4_serial:.2e} -> {'PASS' if t4_serial == 0.0 else 'FAIL'}\")\nprint(f\"[T5a] No-Future-Leakage (Causal Rolling) : {causal_delta:.2e} -> {'PASS' if causal_delta == 0.0 else 'FAIL'}\")\nprint(f\"[T5b] No-Future-Leakage (center=True BUG): {leaky_delta:.2e} -> {'CAUGHT LEAKAGE!' if leaky_delta > 0 else 'MISSED'}\")",
          "expectedOutput": "=== CI/CD Pipeline Invariance & No-Future-Leakage Test Suite ===\n[T1] Determinisme (max delta)            : 0.00e+00 -> PASS\n[T2] Invariansi Permutasi Baris          : 0.00e+00 -> PASS\n[T3] Paritas Single-Row vs Batch (N=80)  : 0.00e+00 -> PASS\n[T4] Round-Trip Serialisasi (SHA=daca98c95e23f54c): 0.00e+00 -> PASS\n[T5a] No-Future-Leakage (Causal Rolling) : 0.00e+00 -> PASS\n[T5b] No-Future-Leakage (center=True BUG): 3.65e+03 -> CAUGHT LEAKAGE!",
          "actualOutput": "=== CI/CD Pipeline Invariance & No-Future-Leakage Test Suite ===\n[T1] Determinisme (max delta)            : 0.00e+00 -> PASS\n[T2] Invariansi Permutasi Baris          : 0.00e+00 -> PASS\n[T3] Paritas Single-Row vs Batch (N=80)  : 0.00e+00 -> PASS\n[T4] Round-Trip Serialisasi (SHA=daca98c95e23f54c): 0.00e+00 -> PASS\n[T5a] No-Future-Leakage (Causal Rolling) : 0.00e+00 -> PASS\n[T5b] No-Future-Leakage (center=True BUG): 3.65e+03 -> CAUGHT LEAKAGE!",
