          "code": "import numpy as np\nimport pandas as pd\nfrom sklearn.compose import ColumnTransformer\nfrom sklearn.ensemble import HistGradientBoostingRegressor\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler\nfrom sklearn.pipeline import Pipeline\n\nrng = np.random.default_rng(2543)\nn_tr = 400\n\n# Model prediksi ETA perjalanan (menit) dari jarak (km), jam sibuk, & tipe kendaraan\ndist_km = rng.uniform(1.0, 25.0, size=n_tr)\nrush = rng.integers(0, 2, size=n_tr)\nvtype = rng.choice([\"BIKE\", \"CAR\"], size=n_tr)\neta_min = 4.0 + 2.3 * dist_km + 6.5 * rush + np.where(vtype == \"CAR\", 3.5, 0.0) + rng.normal(0.0, 1.2, size=n_tr)\n\nX_tr = pd.DataFrame({\"dist_km\": dist_km, \"is_rush\": rush.astype(float), \"vtype\": vtype})\npipe_eta = Pipeline([\n    (\"ct\", ColumnTransformer([\n        (\"num\", StandardScaler(), [\"dist_km\", \"is_rush\"]),\n        (\"cat\", OneHotEncoder(handle_unknown=\"ignore\", sparse_output=False), [\"vtype\"]),\n    ]).set_output(transform=\"pandas\")),\n    (\"reg\", HistGradientBoostingRegressor(max_depth=4, max_iter=60, random_state=42)),\n]).fit(X_tr, eta_min)\n\n# Batch serving sehat (100 perjalanan)\nX_ok = pd.DataFrame({\n    \"dist_km\": rng.uniform(2.0, 18.0, size=100),\n    \"is_rush\": rng.integers(0, 2, size=100).astype(float),\n    \"vtype\": rng.choice([\"BIKE\", \"CAR\"], size=100),\n})\npred_ok = pipe_eta.predict(X_ok)\n\n# Skenario 1: Upstream mengubah satuan km -> meter (1000x!) tanpa notifikasi\nX_unit_bug = X_ok.copy()\nX_unit_bug[\"dist_km\"] = X_unit_bug[\"dist_km\"] * 1000.0\npred_unit_bug = pipe_eta.predict(X_unit_bug)\n\n# Skenario 2: Non-Idempotency Bug (Menerapkan StandardScaler dua kali berturut-turut!)\nscaler_only = pipe_eta.named_steps[\"ct\"].named_transformers_[\"num\"]\nonce_scaled = scaler_only.transform(X_ok[[\"dist_km\", \"is_rush\"]])\ntwice_scaled = scaler_only.transform(pd.DataFrame(once_scaled, columns=[\"dist_km\", \"is_rush\"]))\nidemp_err = float(np.max(np.abs(once_scaled - twice_scaled)))\n\n# Skenario 3: Transformasi Idempoten Sejati (Clip Rentang Fisik [0.5, 100.0])\nclip_once = np.clip(X_ok[\"dist_km\"].to_numpy(), 0.5, 100.0)\nclip_twice = np.clip(clip_once, 0.5, 100.0)\nclip_idemp_err = float(np.max(np.abs(clip_once - clip_twice)))\n\n# Skenario 4: Guard menolak payload korup (1000x unit shift & inf) sebelum masuk model\ndef eta_contract_ok(df: pd.DataFrame) -> tuple[bool, str]:\n    vals = df[\"dist_km\"].to_numpy(dtype=float)\n    if not np.all(np.isfinite(vals)):\n        return False, \"BLOCK:NON_FINITE_DIST\"\n    if float(vals.min()) < 0.1 or float(vals.max()) > 150.0:\n        return False, f\"BLOCK:UNIT_SHIFT_DETECTED(max={vals.max():.1f}km)\"\n    return True, \"PASS\"\n\nok_flag, ok_msg = eta_contract_ok(X_ok)\nbug_flag, bug_msg = eta_contract_ok(X_unit_bug)\nX_inf_bug = X_ok.copy()\nX_inf_bug.loc[0, \"dist_km\"] = np.inf\ninf_flag, inf_msg = eta_contract_ok(X_inf_bug)\n\nprint(\"=== Audit Injeksi Korupsi Senyap & Uji Idempotensi Transformasi ===\")\nprint(f\"Rata-rata ETA Sehat (Baseline)            : {pred_ok.mean():6.2f} menit\")\nprint(f\"Rata-rata ETA Tanpa Guard (Bug 1000x m)   : {pred_unit_bug.mean():6.2f} menit  (Bias = +{pred_unit_bug.mean()-pred_ok.mean():.2f} menit!)\")\nprint(f\"Max |T(x) - T(T(x))| StandardScaler       : {idemp_err:6.3f}  <-- NON-IDEMPOTEN (bahaya retry ganda!)\")\nprint(f\"Max |T(x) - T(T(x))| Physical Clip        : {clip_idemp_err:6.3f}  <-- IDEMPOTEN SEJATI\")\nprint(f\"Guard Check [Clean]                       : {ok_flag} ({ok_msg})\")\nprint(f\"Guard Check [1000x Meter Shift]           : {bug_flag} ({bug_msg})\")\nprint(f\"Guard Check [Inf Poisoning]               : {inf_flag} ({inf_msg})\")",
          "expectedOutput": "=== Audit Injeksi Korupsi Senyap & Uji Idempotensi Transformasi ===\nRata-rata ETA Sehat (Baseline)            :  32.38 menit\nRata-rata ETA Tanpa Guard (Bug 1000x m)   :  64.61 menit  (Bias = +32.23 menit!)\nMax |T(x) - T(T(x))| StandardScaler       :  2.487  <-- NON-IDEMPOTEN (bahaya retry ganda!)\nMax |T(x) - T(T(x))| Physical Clip        :  0.000  <-- IDEMPOTEN SEJATI\nGuard Check [Clean]                       : True (PASS)\nGuard Check [1000x Meter Shift]           : False (BLOCK:UNIT_SHIFT_DETECTED(max=17976.5km))\nGuard Check [Inf Poisoning]               : False (BLOCK:NON_FINITE_DIST)",
          "actualOutput": "=== Audit Injeksi Korupsi Senyap & Uji Idempotensi Transformasi ===\nRata-rata ETA Sehat (Baseline)            :  32.38 menit\nRata-rata ETA Tanpa Guard (Bug 1000x m)   :  64.61 menit  (Bias = +32.23 menit!)\nMax |T(x) - T(T(x))| StandardScaler       :  2.487  <-- NON-IDEMPOTEN (bahaya retry ganda!)\nMax |T(x) - T(T(x))| Physical Clip        :  0.000  <-- IDEMPOTEN SEJATI\nGuard Check [Clean]                       : True (PASS)\nGuard Check [1000x Meter Shift]           : False (BLOCK:UNIT_SHIFT_DETECTED(max=17976.5km))\nGuard Check [Inf Poisoning]               : False (BLOCK:NON_FINITE_DIST)",
