          "starterCode": "import numpy as np\n\ndef ci_pipeline_invariance_audit(series_vals, window: int, t0: int, center_flag: bool) -> tuple[float, bool]:\n    arr = np.asarray(series_vals, dtype=float)\n    # TODO: hitung rolling mean -> perturbasi elemen t > t0 sebesar 50x -> ukur max delta pada indeks 0..t0\n    pass\n\nvals_s = [10.0, 12.0, 11.0, 15.0, 14.0, 16.0, 18.0, 20.0, 19.0, 22.0]\nres_causal = ci_pipeline_invariance_audit(vals_s, window=3, t0=5, center_flag=False)\nres_leaky = ci_pipeline_invariance_audit(vals_s, window=3, t0=5, center_flag=True)\nprint((res_causal[0], res_causal[1], res_leaky[0], res_leaky[1]))",
